-- VERIFICACION de la etapa 1 (y prerequisito de la etapa 2) - solo lectura
-- Base de datos: u611730801_Plataforma (referencias explicitas; NO depende de USE, DATABASE() ni de la base seleccionada en phpMyAdmin: sirve con information_schema, mysql o ninguna).
-- SOLO LECTURA: cada SELECT devuelve (verificacion, resultado). Cualquier DETENER indica que NO debe continuar.
--

SELECT 'quien_lleva VARCHAR(160) NULL sin valor por defecto' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas' AND COLUMN_NAME='quien_lleva' AND COLUMN_TYPE='varchar(160)' AND IS_NULLABLE='YES' AND (COLUMN_DEFAULT IS NULL OR COLUMN_DEFAULT = 'NULL'))=1, 'OK', 'DETENER') AS resultado;
SELECT 'quien_recibe VARCHAR(160) NULL sin valor por defecto' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas' AND COLUMN_NAME='quien_recibe' AND COLUMN_TYPE='varchar(160)' AND IS_NULLABLE='YES' AND (COLUMN_DEFAULT IS NULL OR COLUMN_DEFAULT = 'NULL'))=1, 'OK', 'DETENER') AS resultado;
SELECT 'ninguna venta tiene aun quien_lleva/quien_recibe' AS verificacion, IF((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_ventas WHERE quien_lleva IS NOT NULL OR quien_recibe IS NOT NULL)=0 OR (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bu' AND ACTION_STATEMENT LIKE '%NEW.quien_lleva%' AND ACTION_STATEMENT LIKE '%NEW.quien_recibe%')=1, 'OK', 'DETENER') AS resultado;
SELECT 'triggers de ventas presentes' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bu' AND EVENT_OBJECT_TABLE='canecas_ventas' AND ACTION_STATEMENT LIKE '%CANECAS_VENTA_ANULADA_INMUTABLE%' AND ACTION_STATEMENT LIKE '%NEW.direccion_entrega%')+(SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bu' AND ACTION_STATEMENT LIKE '%NEW.quien_lleva%' AND ACTION_STATEMENT LIKE '%NEW.quien_recibe%')>=1 AND (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bd' AND EVENT_OBJECT_TABLE='canecas_ventas')=1, 'OK', 'DETENER') AS resultado;
SELECT 'recuento canecas_ventas (debe coincidir con el preflight)' AS verificacion, CAST((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_ventas) AS CHAR) AS resultado;
